package com.nvv.mediadata.data.model.tmdbimport com.nvv.mediadata.data.utils.LocalDateSerializerimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializableimport java.time.LocalDate@Serializabledata class Episode(	@SerialName("air_date")	@Serializable(with = LocalDateSerializer::class)	val airDate: LocalDate? = null,	@SerialName("episode_number") val episodeNumber: Int = -1,	@SerialName("episode_type") val episodeType: String = "",	@SerialName("id") val id: Long = -1,	@SerialName("name") val name: String = "",	@SerialName("overview") val overview: String = "",	@SerialName("production_code") val productionCode: String = "",	@SerialName("runtime") val runtime: Int = 0,	@SerialName("season_number") val seasonNumber: Int = -1,	@SerialName("show_id") val showId: Long = -1,	@SerialName("still_path") val stillPath: String? = null,	@SerialName("vote_average") val voteAverage: Double = 0.0,	@SerialName("vote_count") val voteCount: Int = 0,)fun Episode.getStill() : String {	return BaseURLTheMovieDatabaseImage + LogoTheMovieDatabase + (this.stillPath ?: "")}@Serializabledata class SeasonDetail(	@SerialName("id") val id: Long = -1,	@SerialName("_id") val ids: String = "",	@SerialName("air_date")	@Serializable(with = LocalDateSerializer::class)	val airDate: LocalDate? = null,	@SerialName("episodes") val episodes: List<Episode> = emptyList(),	@SerialName("name") val name: String = "",	@SerialName("networks")	val networks: List<Company> = emptyList(),	@SerialName("overview") val overview: String = "",	@SerialName("poster_path") val poster: String? = null,	@SerialName("season_number") val seasonNumber: Int = -1,	@SerialName("vote_average") val voteAverage: Double = 0.0,)